class Solution {
  public int maxRectangleArea(int[][] points) {
    int n = points.length, best = -1;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        int x1 = points[i][0], y1 = points[i][1], x2 = points[j][0], y2 = points[j][1];
        if (x1 >= x2 || y1 >= y2) continue;
        boolean c3 = false, c4 = false, bad = false;
        for (int[] p : points) {
          if (p[0] == x1 && p[1] == y2) c3 = true;
          else if (p[0] == x2 && p[1] == y1) c4 = true;
          else if (p[0] >= x1
              && p[0] <= x2
              && p[1] >= y1
              && p[1] <= y2
              && !(p[0] == x1 && p[1] == y1)
              && !(p[0] == x2 && p[1] == y2)) bad = true;
        }
        if (c3 && c4 && !bad) best = Math.max(best, (x2 - x1) * (y2 - y1));
      }
    }
    return best;
  }
}
